    insert into public.restaurantes (slug, nombre) values ('il-paparazzo', 'Il Paparazzo') returning id into rid;
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Menú Vera Pasta', 0, '{"en": {"nombre": "Vera Pasta Menu"}, "pt": {"nombre": "Menu Massa de Verdade"}, "it": {"nombre": "Menù Vera Pasta"}, "de": {"nombre": "Menü Echte Pasta"}, "fr": {"nombre": "Menu Vraies Pâtes"}, "nl": {"nombre": "Menu Echte Pasta"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Menú Vera Pasta', 'Entrada + principal + postre. Más de 30 combinaciones para elegir, todas con pasta fresca hecha en casa.', 17900, '{}', 0, true, '{"en": {"nombre": "Vera Pasta Menu", "descripcion": "Starter + main course + dessert. More than 30 combinations to choose from, all with fresh homemade pasta."}, "pt": {"nombre": "Menu Massa de Verdade", "descripcion": "Entrada + prato principal + sobremesa. Mais de 30 combinações para escolher, todas com massa fresca caseira."}, "it": {"nombre": "Menù Vera Pasta", "descripcion": "Antipasto + primo + dolce. Oltre 30 combinazioni tra cui scegliere, tutte con pasta fresca fatta in casa."}, "de": {"nombre": "Menü Echte Pasta", "descripcion": "Vorspeise + Hauptgericht + Dessert. Über 30 Kombinationen zur Auswahl, alle mit frischer hausgemachter Pasta."}, "fr": {"nombre": "Menu Vraies Pâtes", "descripcion": "Entrée + plat + dessert. Plus de 30 combinaisons au choix, toutes avec des pâtes fraîches maison."}, "nl": {"nombre": "Menu Echte Pasta", "descripcion": "Voorgerecht + hoofdgerecht + dessert. Meer dan 30 combinaties om uit te kiezen, allemaal met verse huisgemaakte pasta."}}'::jsonb, '[{"nombre": "Entrada", "min": 1, "max": 1, "valores": [{"nombre": "Ceviche pescado del día", "precio": 0}, {"nombre": "Ceviche de champiñones", "precio": 0}, {"nombre": "Ensalada mediterránea", "precio": 0}]}, {"nombre": "Principal", "min": 1, "max": 1, "valores": [{"nombre": "Panzotti de espinaca y ricotta", "precio": 0}, {"nombre": "Raviolo de salmón", "precio": 0}, {"nombre": "Raviolo Il Bambino", "precio": 0}, {"nombre": "Panzotti de alcachofa", "precio": 0}, {"nombre": "Raviolo de carne mechada", "precio": 0}, {"nombre": "Raviolo de camarones", "precio": 0}, {"nombre": "Sorrentino al funghi", "precio": 0}, {"nombre": "Raviolo de berenjenas", "precio": 0}, {"nombre": "Pasta al huevo con salsa a elección", "precio": 0}, {"nombre": "Pasta vegana con salsa a elección", "precio": 0}, {"nombre": "Risotto nero y camarones", "precio": 0}, {"nombre": "Risotto de setas", "precio": 0}]}, {"nombre": "Postre", "min": 1, "max": 1, "valores": [{"nombre": "Tiramisú", "precio": 0}, {"nombre": "Panna cotta", "precio": 0}, {"nombre": "Helado", "precio": 0}, {"nombre": "Panna cotta vegana", "precio": 0}, {"nombre": "Helado vegano", "precio": 0}]}]'::jsonb, 'pasta');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Entradas', 1, '{"en": {"nombre": "Starters"}, "pt": {"nombre": "Entradas"}, "it": {"nombre": "Antipasti"}, "de": {"nombre": "Vorspeisen"}, "fr": {"nombre": "Entrées"}, "nl": {"nombre": "Voorgerechten"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Ceviche pescado del día', 'Cubos de pescado marinados con limón, cilantro, leche evaporada y jengibre; servido con cebolla morada, palta y pimentones.', 8900, '{}', 0, false, '{"en": {"nombre": "Catch of the day ceviche", "descripcion": "Fish cubes marinated with lime, coriander, evaporated milk and ginger; served with red onion, avocado and bell peppers."}, "pt": {"nombre": "Ceviche de peixe do dia", "descripcion": "Cubos de peixe marinados com limão, coentro, leite evaporado e gengibre; servido com cebola roxa, abacate e pimentões."}, "it": {"nombre": "Ceviche di pesce del giorno", "descripcion": "Cubetti di pesce marinati con limone, coriandolo, latte evaporato e zenzero; serviti con cipolla rossa, avocado e peperoni."}, "de": {"nombre": "Ceviche vom Tagesfisch", "descripcion": "Fischwürfel mariniert mit Limette, Koriander, Kondensmilch und Ingwer; serviert mit roten Zwiebeln, Avocado und Paprika."}, "fr": {"nombre": "Ceviche du poisson du jour", "descripcion": "Dés de poisson marinés au citron vert, coriandre, lait concentré et gingembre ; servis avec oignon rouge, avocat et poivrons."}, "nl": {"nombre": "Ceviche van de vis van de dag", "descripcion": "Visblokjes gemarineerd met limoen, koriander, gecondenseerde melk en gember; geserveerd met rode ui, avocado en paprika."}}'::jsonb, '[]'::jsonb, 'pescado');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Ceviche de champiñones', 'Champiñones confitados, mix de quínoa, palmitos, palta y cebolla morada, marinados en jugo de limón, aceite de oliva y cilantro.', 7900, '{"vegano"}', 1, false, '{"en": {"nombre": "Mushroom ceviche", "descripcion": "Confit mushrooms, quinoa mix, hearts of palm, avocado and red onion, marinated in lime juice, olive oil and coriander."}, "pt": {"nombre": "Ceviche de cogumelos", "descripcion": "Cogumelos confitados, mix de quinoa, palmito, abacate e cebola roxa, marinados em suco de limão, azeite e coentro."}, "it": {"nombre": "Ceviche ai funghi", "descripcion": "Funghi confit, mix di quinoa, cuori di palma, avocado e cipolla rossa, marinati in succo di limone, olio d''oliva e coriandolo."}, "de": {"nombre": "Pilz-Ceviche", "descripcion": "Confierte Pilze, Quinoa-Mix, Palmherzen, Avocado und rote Zwiebeln, mariniert in Limettensaft, Olivenöl und Koriander."}, "fr": {"nombre": "Ceviche aux champignons", "descripcion": "Champignons confits, mélange de quinoa, cœurs de palmier, avocat et oignon rouge, marinés au jus de citron, huile d''olive et coriandre."}, "nl": {"nombre": "Champignonceviche", "descripcion": "Gekonfijte champignons, quinoamix, palmharten, avocado en rode ui, gemarineerd in limoensap, olijfolie en koriander."}}'::jsonb, '[]'::jsonb, 'champinon');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Ensalada mediterránea', 'Lechuga, rúcula, aceitunas, queso parmesano o queso vegano, pimientos asados, tomates secos, champiñones confitados y aderezo.', 7900, '{"vegano"}', 2, false, '{"en": {"nombre": "Mediterranean salad", "descripcion": "Lettuce, arugula, olives, Parmesan or vegan cheese, roasted peppers, sun-dried tomatoes, confit mushrooms and dressing."}, "pt": {"nombre": "Salada mediterrânea", "descripcion": "Alface, rúcula, azeitonas, parmesão ou queijo vegano, pimentões assados, tomates secos, cogumelos confitados e molho."}, "it": {"nombre": "Insalata mediterranea", "descripcion": "Lattuga, rucola, olive, parmigiano o formaggio vegano, peperoni arrostiti, pomodori secchi, funghi confit e condimento."}, "de": {"nombre": "Mediterraner Salat", "descripcion": "Salat, Rucola, Oliven, Parmesan oder veganer Käse, geröstete Paprika, getrocknete Tomaten, confierte Pilze und Dressing."}, "fr": {"nombre": "Salade méditerranéenne", "descripcion": "Laitue, roquette, olives, parmesan ou fromage végétal, poivrons rôtis, tomates séchées, champignons confits et vinaigrette."}, "nl": {"nombre": "Mediterrane salade", "descripcion": "Sla, rucola, olijven, Parmezaanse of vegan kaas, geroosterde paprika, zongedroogde tomaten, gekonfijte champignons en dressing."}}'::jsonb, '[]'::jsonb, 'ensalada');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Pastas rellenas al huevo', 2, '{"en": {"nombre": "Filled egg pasta"}, "pt": {"nombre": "Massas recheadas de ovo"}, "it": {"nombre": "Pasta ripiena all''uovo"}, "de": {"nombre": "Gefüllte Eiernudeln"}, "fr": {"nombre": "Pâtes farcies aux œufs"}, "nl": {"nombre": "Gevulde eierpasta"}}'::jsonb, 'Cocina') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Panzotti de espinaca y ricotta', 'Pasta rellena de espinaca, ricotta, queso parmesano y nuez moscada; en salsa de tomate pomodoro, chiffonade de albahaca y queso parmesano.', 13900, '{"vegetariano"}', 0, false, '{"en": {"nombre": "Spinach and ricotta panzotti", "descripcion": "Pasta filled with spinach, ricotta, Parmesan and nutmeg; in pomodoro tomato sauce with basil chiffonade and Parmesan."}, "pt": {"nombre": "Panzotti de espinafre e ricota", "descripcion": "Massa recheada com espinafre, ricota, parmesão e noz-moscada; ao molho de tomate pomodoro, chiffonade de manjericão e parmesão."}, "it": {"nombre": "Panzotti ricotta e spinaci", "descripcion": "Pasta ripiena di spinaci, ricotta, parmigiano e noce moscata; in salsa di pomodoro, chiffonade di basilico e parmigiano."}, "de": {"nombre": "Spinat-Ricotta-Panzotti", "descripcion": "Mit Spinat, Ricotta, Parmesan und Muskatnuss gefüllte Pasta; in Pomodoro-Tomatensauce mit Basilikum-Chiffonade und Parmesan."}, "fr": {"nombre": "Panzotti épinards et ricotta", "descripcion": "Pâtes farcies aux épinards, ricotta, parmesan et noix de muscade ; sauce tomate pomodoro, chiffonnade de basilic et parmesan."}, "nl": {"nombre": "Panzotti met spinazie en ricotta", "descripcion": "Pasta gevuld met spinazie, ricotta, Parmezaanse kaas en nootmuskaat; in pomodorosaus met basilicumchiffonade en Parmezaanse kaas."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Raviolo de salmón', 'Pasta atomatada rellena de salmón sellado, ricotta, pimientos asados a las brasas y ciboulette; en salsa de vino blanco, crema, hierbas de Provenza y ralladura de pistacho.', 14900, '{}', 1, true, '{"en": {"nombre": "Salmon raviolo", "descripcion": "Tomato pasta filled with seared salmon, ricotta, flame-roasted peppers and chives; in a white wine and cream sauce with herbes de Provence and grated pistachio."}, "pt": {"nombre": "Ravioli de salmão", "descripcion": "Massa de tomate recheada com salmão selado, ricota, pimentões assados na brasa e cebolinha; em molho de vinho branco, creme, ervas de Provença e raspas de pistache."}, "it": {"nombre": "Raviolo di salmone", "descripcion": "Pasta al pomodoro ripiena di salmone scottato, ricotta, peperoni alla brace ed erba cipollina; in salsa di vino bianco, panna, erbe di Provenza e granella di pistacchio."}, "de": {"nombre": "Lachs-Raviolo", "descripcion": "Tomatenpasta gefüllt mit angebratenem Lachs, Ricotta, gegrillter Paprika und Schnittlauch; in Weißwein-Sahnesauce mit Kräutern der Provence und Pistazien."}, "fr": {"nombre": "Raviolo au saumon", "descripcion": "Pâte à la tomate farcie de saumon saisi, ricotta, poivrons grillés et ciboulette ; sauce au vin blanc et crème, herbes de Provence et pistache râpée."}, "nl": {"nombre": "Zalmraviolo", "descripcion": "Tomatenpasta gevuld met dichtgeschroeide zalm, ricotta, gegrilde paprika en bieslook; in witte wijn-roomsaus met Provençaalse kruiden en geraspte pistache."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Raviolo Il Bambino', 'Pasta bicolor rellena de jamón y mozzarella en salsa pomodoro, queso parmesano y chiffonade de albahaca.', 12900, '{}', 2, false, '{"en": {"nombre": "Il Bambino raviolo", "descripcion": "Two-colour pasta filled with ham and mozzarella in pomodoro sauce, Parmesan and basil chiffonade."}, "pt": {"nombre": "Ravioli Il Bambino", "descripcion": "Massa bicolor recheada com presunto e muçarela ao molho pomodoro, parmesão e chiffonade de manjericão."}, "it": {"nombre": "Raviolo Il Bambino", "descripcion": "Pasta bicolore ripiena di prosciutto e mozzarella in salsa di pomodoro, parmigiano e chiffonade di basilico."}, "de": {"nombre": "Raviolo Il Bambino", "descripcion": "Zweifarbige Pasta gefüllt mit Schinken und Mozzarella in Pomodoro-Sauce, Parmesan und Basilikum-Chiffonade."}, "fr": {"nombre": "Raviolo Il Bambino", "descripcion": "Pâtes bicolores farcies au jambon et à la mozzarella, sauce pomodoro, parmesan et chiffonnade de basilic."}, "nl": {"nombre": "Raviolo Il Bambino", "descripcion": "Tweekleurige pasta gevuld met ham en mozzarella in pomodorosaus, Parmezaanse kaas en basilicumchiffonade."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Panzotti de alcachofa', 'Pasta rellena de alcachofa, ricotta y queso parmesano, en reducción de vino blanco, crema y vegetales salteados (espárragos, tomates cherry y champiñones confitados).', 13900, '{"vegetariano"}', 3, false, '{"en": {"nombre": "Artichoke panzotti", "descripcion": "Pasta filled with artichoke, ricotta and Parmesan, in a white wine reduction with cream and sautéed vegetables (asparagus, cherry tomatoes and confit mushrooms)."}, "pt": {"nombre": "Panzotti de alcachofra", "descripcion": "Massa recheada com alcachofra, ricota e parmesão, em redução de vinho branco, creme e legumes salteados (aspargos, tomate-cereja e cogumelos confitados)."}, "it": {"nombre": "Panzotti ai carciofi", "descripcion": "Pasta ripiena di carciofi, ricotta e parmigiano, con riduzione di vino bianco, panna e verdure saltate (asparagi, pomodorini e funghi confit)."}, "de": {"nombre": "Artischocken-Panzotti", "descripcion": "Mit Artischocke, Ricotta und Parmesan gefüllte Pasta in Weißweinreduktion mit Sahne und sautiertem Gemüse (Spargel, Kirschtomaten, confierte Pilze)."}, "fr": {"nombre": "Panzotti à l''artichaut", "descripcion": "Pâtes farcies à l''artichaut, ricotta et parmesan, réduction au vin blanc, crème et légumes sautés (asperges, tomates cerises et champignons confits)."}, "nl": {"nombre": "Panzotti met artisjok", "descripcion": "Pasta gevuld met artisjok, ricotta en Parmezaanse kaas, in een witte wijnreductie met room en gebakken groenten (asperges, kerstomaatjes en gekonfijte champignons)."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Raviolo de carne mechada', 'Pasta rellena de carne guisada en verduras con queso mozzarella; en salsa pomodoro, chiffonade de albahaca y queso parmesano.', 13900, '{}', 4, false, '{"en": {"nombre": "Shredded beef raviolo", "descripcion": "Pasta filled with beef stewed in vegetables and mozzarella; in pomodoro sauce with basil chiffonade and Parmesan."}, "pt": {"nombre": "Ravioli de carne desfiada", "descripcion": "Massa recheada com carne ensopada com legumes e muçarela; ao molho pomodoro, chiffonade de manjericão e parmesão."}, "it": {"nombre": "Raviolo di carne sfilacciata", "descripcion": "Pasta ripiena di carne stufata con verdure e mozzarella; in salsa di pomodoro, chiffonade di basilico e parmigiano."}, "de": {"nombre": "Raviolo mit Schmorfleisch", "descripcion": "Pasta gefüllt mit in Gemüse geschmortem Rindfleisch und Mozzarella; in Pomodoro-Sauce mit Basilikum-Chiffonade und Parmesan."}, "fr": {"nombre": "Raviolo à l''effiloché de bœuf", "descripcion": "Pâtes farcies de bœuf mijoté aux légumes et mozzarella ; sauce pomodoro, chiffonnade de basilic et parmesan."}, "nl": {"nombre": "Raviolo met draadjesvlees", "descripcion": "Pasta gevuld met in groenten gestoofd rundvlees en mozzarella; in pomodorosaus met basilicumchiffonade en Parmezaanse kaas."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Raviolo de camarones', 'Pasta rellena de camarones salteados en oliva, cebolla brunoise, ciboulette, ricotta y curry; en salsa cremosa con toques de queso azul, crema y vino blanco.', 14900, '{}', 5, false, '{"en": {"nombre": "Shrimp raviolo", "descripcion": "Pasta filled with shrimp sautéed in olive oil, brunoise onion, chives, ricotta and curry; in a creamy sauce with blue cheese, cream and white wine."}, "pt": {"nombre": "Ravioli de camarão", "descripcion": "Massa recheada com camarão salteado no azeite, cebola brunoise, cebolinha, ricota e curry; em molho cremoso com queijo azul, creme e vinho branco."}, "it": {"nombre": "Raviolo di gamberi", "descripcion": "Pasta ripiena di gamberi saltati in olio d''oliva, cipolla brunoise, erba cipollina, ricotta e curry; in salsa cremosa con gorgonzola, panna e vino bianco."}, "de": {"nombre": "Garnelen-Raviolo", "descripcion": "Pasta gefüllt mit in Olivenöl sautierten Garnelen, Zwiebelbrunoise, Schnittlauch, Ricotta und Curry; in cremiger Sauce mit Blauschimmelkäse, Sahne und Weißwein."}, "fr": {"nombre": "Raviolo aux crevettes", "descripcion": "Pâtes farcies de crevettes sautées à l''huile d''olive, oignon brunoise, ciboulette, ricotta et curry ; sauce crémeuse au bleu, crème et vin blanc."}, "nl": {"nombre": "Garnalenraviolo", "descripcion": "Pasta gevuld met in olijfolie gebakken garnalen, brunoise van ui, bieslook, ricotta en curry; in romige saus met blauwe kaas, room en witte wijn."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Sorrentino al funghi', 'Pasta rellena de champiñones salteados con mix de verduras y pimientos asados, con salsa pomodoro o salsa rosa (pomodoro y crema vegana).', 13900, '{"vegano"}', 6, false, '{"en": {"nombre": "Mushroom sorrentino", "descripcion": "Pasta filled with sautéed mushrooms, mixed vegetables and roasted peppers, with pomodoro or pink sauce (pomodoro and vegan cream)."}, "pt": {"nombre": "Sorrentino de cogumelos", "descripcion": "Massa recheada com cogumelos salteados, legumes e pimentões assados, com molho pomodoro ou rosé (pomodoro e creme vegano)."}, "it": {"nombre": "Sorrentino ai funghi", "descripcion": "Pasta ripiena di funghi saltati, verdure miste e peperoni arrostiti, con salsa di pomodoro o salsa rosa (pomodoro e panna vegana)."}, "de": {"nombre": "Sorrentino mit Pilzen", "descripcion": "Pasta gefüllt mit sautierten Champignons, gemischtem Gemüse und gerösteter Paprika, mit Pomodoro- oder Rosa-Sauce (Pomodoro und vegane Sahne)."}, "fr": {"nombre": "Sorrentino aux champignons", "descripcion": "Pâtes farcies de champignons sautés, légumes variés et poivrons rôtis, sauce pomodoro ou sauce rose (pomodoro et crème végétale)."}, "nl": {"nombre": "Sorrentino met champignons", "descripcion": "Pasta gevuld met gebakken champignons, gemengde groenten en geroosterde paprika, met pomodorosaus of roze saus (pomodoro en vegan room)."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Raviolo de berenjenas', 'Pasta de cacao rellena de berenjenas asadas, castañas de cajú, ajo, cebollín y queso vegano; en salsa de vino dulce tinto, crema vegana, nueces y vegetales salteados.', 13900, '{"vegano"}', 7, true, '{"en": {"nombre": "Eggplant raviolo", "descripcion": "Cocoa pasta filled with roasted eggplant, cashews, garlic, spring onion and vegan cheese; in a sweet red wine sauce with vegan cream, walnuts and sautéed vegetables."}, "pt": {"nombre": "Ravioli de berinjela", "descripcion": "Massa de cacau recheada com berinjela assada, castanha de caju, alho, cebolinha e queijo vegano; em molho de vinho tinto doce, creme vegano, nozes e legumes salteados."}, "it": {"nombre": "Raviolo di melanzane", "descripcion": "Pasta al cacao ripiena di melanzane arrostite, anacardi, aglio, cipollotto e formaggio vegano; in salsa di vino rosso dolce, panna vegana, noci e verdure saltate."}, "de": {"nombre": "Auberginen-Raviolo", "descripcion": "Kakaopasta gefüllt mit gerösteten Auberginen, Cashewkernen, Knoblauch, Frühlingszwiebel und veganem Käse; in süßer Rotweinsauce mit veganer Sahne, Walnüssen und Gemüse."}, "fr": {"nombre": "Raviolo d''aubergine", "descripcion": "Pâte au cacao farcie d''aubergines rôties, noix de cajou, ail, cébette et fromage végétal ; sauce au vin rouge doux, crème végétale, noix et légumes sautés."}, "nl": {"nombre": "Aubergineraviolo", "descripcion": "Cacaopasta gevuld met geroosterde aubergine, cashewnoten, knoflook, lente-ui en vegan kaas; in zoete rodewijnsaus met vegan room, walnoten en gebakken groenten."}}'::jsonb, '[]'::jsonb, 'pasta');
  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Pastas con salsa a elección', 3, '{"en": {"nombre": "Pasta with your choice of sauce"}, "pt": {"nombre": "Massas com molho à escolha"}, "it": {"nombre": "Pasta con salsa a scelta"}, "de": {"nombre": "Pasta mit Soße nach Wahl"}, "fr": {"nombre": "Pâtes avec sauce au choix"}, "nl": {"nombre": "Pasta met saus naar keuze"}}'::jsonb, 'Cocina') returning id into cid;
