  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Otras cepas tintas · solo para curiosos', 9, '{"en": {"nombre": "Rare red grapes · for the curious"}, "pt": {"nombre": "Outras uvas tintas · para curiosos"}, "it": {"nombre": "Altri vitigni rossi · per curiosi"}, "de": {"nombre": "Seltene rote Rebsorten · für Neugierige"}, "fr": {"nombre": "Autres cépages rouges · pour les curieux"}, "nl": {"nombre": "Andere rode druiven · voor nieuwsgierigen"}}'::jsonb, 'Barra') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Casa Silva', 'Romano o César Noir · D.O. Colchagua. Crianza, 50% se guardó en barricas francesas de segundo uso por seis meses y el 50% restante se mantuvo en tanques de acero inoxidable. Parras plantadas en 1912. Color rojo guinda de intensidad media.', 32000, '{}', 0, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'De Martino, Ungrafted Old Vines', 'Cinsault · D.O. Itata, Guarilihue. Color rubí brillante, de intensidad moderada. Perfumado y con aromas frescos de guindas rojas y oscuras, con una nota a violeta combinada con un ligero toque picante.', 28900, '{}', 1, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Luis Felipe Edwards, 360°', 'Sangiovese · D.O. Colchagua. Color rojo granate con intensos matices violáceos. Notas aromáticas frutales a ciruela y mora acompañadas de aromas tostados de fondo. Acidez fresca y taninos maduros presentes en retrogusto.', 27600, '{}', 2, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Luis Felipe Edwards, 360°', 'Tempranillo · D.O. Alto Colchagua. Variedad tinta no tradicional, de origen español Rojo granate. Aromas a frutilla, frambuesa, mora, guinda, hierba fresca, clavo de olor.', 27600, '{}', 3, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Lagar de Codegua', 'Mourvedre · D.O. Alto Cachapoal. Crianza en barrica francesa de tercer y cuarto uso por 12 meses. Presenta toques de grafito, arándanos, frutas maduras y notas de hierbas y especias. Frescor interesante y rica acidez, largo final.', 27600, '{}', 4, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Schwaderer Wines', 'Garnacha · D.O. Colchagua', 26800, '{}', 5, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Choapa Wines, Cordilleramar', 'Cabernet Franc · D.O. Choapa. Rojo intenso, matiz rojizo y muy macizo. Rico ataque, con balance y equilibrio siempre. Acidez media y de retrogusto largo y persistente. Vino de volumen y cuerpo medio alto.', 26800, '{}', 6, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Montes, Outer Limits', 'Cinsault · D.O. Itata. Presenta un llamativo color rojo magenta, muy típico de esta variedad. Sus aromas son muy frescos, de frutos azules y rojos como frambuesas, arándanos, albaricoque y moras.', 26400, '{}', 7, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Chateau Los Boldos', 'Touriga Nacional · D.O. Cachapoal Andes. Es un vino de color rojo carmín profundo.', 26000, '{}', 8, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Casa Silva', 'Petit Verdot · D.O. Colchagua. Variedad tinta originaria de la región de Burdeos. Vino de color rojo púrpura intenso y brillante. Aromas a moras, higos maduros, cuero, tabaco, cedro y violetas.', 25900, '{}', 9, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Odfjell, Orzada', 'Tannat · D.O. Cauquenes. En nariz es intenso, con notas de cerezas, fresas y ciruelas pasas acompañadas de ciertas notas especiadas como pimienta negra. Se expande en boca con taninos potentes pero aterciopelados.', 25400, '{}', 10, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Korta', 'Grosse Merille (Verdot chileno) · D.O. Sagrada Familia. De lenta maduración en climas cálidos y color muy ligero, su fortaleza proviene de su floralidad que recuerda pétalos de rosas, flores blancas y rojas, frutos rojos frescos.', 22000, '{}', 11, false, '{}'::jsonb, '[]'::jsonb, 'vino');
