  insert into public.categorias (restaurante_id, nombre, orden, traducciones, estacion) values (rid, 'Otras cepas blancas · solo para curiosos', 12, '{"en": {"nombre": "Rare white grapes · for the curious"}, "pt": {"nombre": "Outras uvas brancas · para curiosos"}, "it": {"nombre": "Altri vitigni bianchi · per curiosi"}, "de": {"nombre": "Seltene weiße Rebsorten · für Neugierige"}, "fr": {"nombre": "Autres cépages blancs · pour les curieux"}, "nl": {"nombre": "Andere witte druiven · voor nieuwsgierigen"}}'::jsonb, 'Barra') returning id into cid;
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'El Principal, KIÑE', 'Verdejo · D.O. Maipo Andes. Verdejo Chileno. Dorado amarillo, Nariz madura, caramelo, papaya, mineral, cítricos maduros. En boca tiene una acidez media, buen cuerpo, agradable, levemente dulce.', 29800, '{}', 0, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Schwaderer Wines', 'Riesling · D.O. Cauquenes. Nariz intensa, suaves azahares, flor de sauco, zeste de lima, hierba buena, melón tuna, nísperos maduros. Profundo y sedoso en boca, balanceado, acidez equilibrada y suave dulzor.', 25600, '{}', 1, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Casa Silva, Cool Coast', 'Sauvignon Gris · D.O. Colchagua. Notas florales, limón amarillo, pera blanca, piña fresca y hojas de laurel. En boca acidez alta, fresco de buen volumen y carácter, aparecen sabores herbáceos y cítricos con leve dejo de salinidad.', 26000, '{}', 2, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'J. Bouchon, País Salvaje', 'País blanco · D.O. Maule. El mosto fue guardado en ánforas de greda, las que aportaron micro- oxigenación, dando más complejidad. El vino no fue filtrado ni clarificado.', 25600, '{}', 3, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Chateau Los Boldos', 'Friulano · D.O. Cachapoal Andes. Color Amarillo pálido con reflejos verdosos. Una nariz sutil con aromas frutales a melón, damascos, pera y alcayota.', 24000, '{}', 4, false, '{}'::jsonb, '[]'::jsonb, 'vino');
  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Viña Longavi, GLUP', 'Chenin Blanc · D.O. Maule', 24900, '{}', 5, false, '{}'::jsonb, '[]'::jsonb, 'vino');
