  insert into public.platos (restaurante_id, categoria_id, nombre, descripcion, precio, etiquetas, orden, destacado, traducciones, opciones, icono) values (rid, cid, 'Grabados de Choapa', 'Moscatel de Austria · D.O. Choapa. Amarillo pálido, brillante limpio y de buena intensidad, con matices verdosos. Balanceado y más fenólico lo que da una sensación de más boca y volumen. Persistente en final de boca, gran acidez.', 18900, '{}', 9, false, '{}'::jsonb, '[]'::jsonb, 'vino');
