-- Carta de demostración "Il Paparazzo · Ristorante & Winebar" (Valparaíso), para mostrársela al restaurante.
-- Hecha con sus cartas reales: Menú Vera Pasta en 7 idiomas (español, inglés, portugués, italiano, alemán, francés y
-- holandés), carta de Gin & Tonic y carta de vinos 2026 con sus precios.
-- OJO: los precios de los platos son de referencia (sus PDF de pastas no traen precios); gin y vinos sí son los reales.
-- Requiere la migración 0034 (holandés y reservas por turno). Se puede ejecutar más de una vez: borra y vuelve a crear
-- la carta de la demo (categorías y platos), sin tocar reservas ni nada más.

do $$
declare
  rid uuid;
  cid uuid;
begin
  select id into rid from public.restaurantes where slug = 'il-paparazzo';
  if rid is null then
  end if;

  update public.restaurantes set
    nombre = 'Il Paparazzo',
    descripcion = 'Ristorante & Winebar · Pasta fresca hecha en casa en Valparaíso',
    logo_url = '/demo/il-paparazzo/logo.png',
    tema = 'trattoria',
    color_primario = '#c8102e',
    color_fondo = '#151515',
    moneda = 'CLP',
    idiomas = array['en', 'pt', 'it', 'de', 'fr', 'nl'],
    traducciones = '{"en": {"descripcion": "Ristorante & Winebar · Fresh homemade pasta in Valparaíso"}, "pt": {"descripcion": "Ristorante & Winebar · Massa fresca caseira em Valparaíso"}, "it": {"descripcion": "Ristorante & Winebar · Pasta fresca fatta in casa a Valparaíso"}, "de": {"descripcion": "Ristorante & Winebar · Frische hausgemachte Pasta in Valparaíso"}, "fr": {"descripcion": "Ristorante & Winebar · Pâtes fraîches maison à Valparaíso"}, "nl": {"descripcion": "Ristorante & Winebar · Verse huisgemaakte pasta in Valparaíso"}}'::jsonb,
    ajustes = ajustes || '{"pais": "CL", "zona_horaria": "America/Santiago", "imagenes_defecto": true, "modulos": {"reservas": true}, "reservas": {"online": true, "tolerancia": 15, "mostrar_tolerancia": true, "recordatorio": true, "horas_antes": 3, "ninos": true, "correo": "opcional", "ubicaciones": ["Salón interior", "Terraza exterior"], "turnos": [{"nombre": "Almuerzo", "desde": "12:30", "hasta": "15:30", "cada": 30, "dias": [], "cupo": 0}, {"nombre": "Cena", "desde": "18:30", "hasta": "20:30", "cada": 30, "dias": [], "cupo": 0}]}}'::jsonb
  where id = rid;

  delete from public.platos where restaurante_id = rid;
  delete from public.categorias where restaurante_id = rid;

end $$;
